<style>
  :root {
    --bg: #f5f3ee; --surface: #fffdf9; --ink: #1d1b16; --ink-2: #4a463d; --ink-3: #7a7466;
    --hair: #e2ddd2; --hair-2: #cfc8b9; --accent: #1f5f8b; --accent-ink: #ffffff;
    --paper: #1f5f8b; --project: #b0532a; --org: #6d5a3c; --dataset: #2f7a5f; --finding: #8a2f5b; --principle: #5b4a9a; --workflow: #b5851f; --package: #2b6f6f; --post: #8c6d1f;
    --good: #2f7a5f; --warn: #b5851f; --bad: #a8352f;
  }
  @media (prefers-color-scheme: dark) {
    :root:not([data-theme="light"]) {
      --bg: #141310; --surface: #1c1a16; --ink: #ece7dc; --ink-2: #bdb6a7; --ink-3: #8d8677;
      --hair: #2c2924; --hair-2: #3d392f; --accent: #7fb3d8; --accent-ink: #0f1a22;
      --paper: #7fb3d8; --project: #e2916a; --org: #c4a67a; --dataset: #7cc4a5; --finding: #d98ab3; --principle: #a99ad9; --workflow: #e0b45a; --package: #7cc0c0; --post: #d4b05a;
      --good: #7cc4a5; --warn: #e0b45a; --bad: #e07f79;
    }
  }
  :root[data-theme="dark"] {
    --bg: #141310; --surface: #1c1a16; --ink: #ece7dc; --ink-2: #bdb6a7; --ink-3: #8d8677;
    --hair: #2c2924; --hair-2: #3d392f; --accent: #7fb3d8; --accent-ink: #0f1a22;
    --paper: #7fb3d8; --project: #e2916a; --org: #c4a67a; --dataset: #7cc4a5; --finding: #d98ab3; --principle: #a99ad9; --workflow: #e0b45a; --package: #7cc0c0; --post: #d4b05a;
    --good: #7cc4a5; --warn: #e0b45a; --bad: #e07f79;
  }
  * { box-sizing: border-box; }
  body { margin: 0; background: var(--bg); color: var(--ink); font: 15px/1.5 "IBM Plex Sans", system-ui, sans-serif; }
  a { color: var(--accent); }
  .mono { font-family: "IBM Plex Mono", ui-monospace, monospace; font-size: 12.5px; }
  header { padding: 28px 28px 14px; border-bottom: 1px solid var(--hair); background: var(--surface); }
  header h1 { font: 700 34px/1.1 Fraunces, Georgia, serif; margin: 0 0 6px; text-wrap: balance; letter-spacing: -0.01em; }
  header p { margin: 0; color: var(--ink-2); max-width: 70ch; }
  .stats { display: flex; flex-wrap: wrap; gap: 8px 22px; margin-top: 14px; font-variant-numeric: tabular-nums; }
  .stats span b { font-family: Fraunces, Georgia, serif; font-size: 22px; font-weight: 700; margin-right: 6px; }
  .stats span { color: var(--ink-2); font-size: 13px; }
  .layout { display: grid; grid-template-columns: 280px minmax(0, 1fr) 380px; min-height: 70vh; }
  @media (max-width: 1100px) { .layout { grid-template-columns: 1fr; } aside.filters { border-right: 0; border-bottom: 1px solid var(--hair); } aside.detail { border-left: 0; border-top: 1px solid var(--hair); } }
  aside.filters { border-right: 1px solid var(--hair); padding: 16px 18px; display: flex; flex-direction: column; gap: 16px; }
  aside.detail { border-left: 1px solid var(--hair); padding: 18px; background: var(--surface); min-height: 360px; }
  .eyebrow { font: 500 11px/1 "IBM Plex Mono", monospace; letter-spacing: 0.12em; text-transform: uppercase; color: var(--ink-3); margin: 0 0 8px; }
  input[type="search"] { width: 100%; padding: 9px 11px; border: 1px solid var(--hair-2); border-radius: 6px; background: var(--surface); color: var(--ink); font: inherit; }
  input[type="search"]:focus { outline: 2px solid var(--accent); outline-offset: 1px; }
  .chips { display: flex; flex-wrap: wrap; gap: 6px; }
  .chip { border: 1px solid var(--hair-2); background: var(--surface); color: var(--ink-2); border-radius: 999px; padding: 4px 10px; font-size: 12.5px; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; }
  .chip .dot { width: 9px; height: 9px; border-radius: 50%; background: var(--c, var(--ink-3)); }
  .chip[aria-pressed="true"] { background: var(--ink); color: var(--bg); border-color: var(--ink); }
  .chip:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
  .graph-wrap { position: relative; background: var(--bg); overflow: hidden; }
  canvas { display: block; width: 100%; height: 100%; cursor: grab; }
  .hint { position: absolute; left: 14px; bottom: 12px; font-size: 12px; color: var(--ink-3); background: var(--surface); border: 1px solid var(--hair); border-radius: 6px; padding: 4px 8px; }
  .legend { position: absolute; right: 14px; top: 12px; display: grid; gap: 4px; background: var(--surface); border: 1px solid var(--hair); border-radius: 8px; padding: 8px 10px; font-size: 12px; }
  .legend div { display: flex; align-items: center; gap: 7px; color: var(--ink-2); }
  .legend i { width: 10px; height: 10px; border-radius: 50%; display: inline-block; background: var(--c); }
  .detail h2 { font: 700 20px/1.2 Fraunces, Georgia, serif; margin: 0 0 6px; text-wrap: balance; }
  .detail .meta { color: var(--ink-3); font-size: 12.5px; margin-bottom: 10px; }
  .detail p { margin: 0 0 10px; color: var(--ink-2); }
  .tag { display: inline-block; border-radius: 4px; padding: 1px 6px; font-size: 11.5px; font-family: "IBM Plex Mono", monospace; border: 1px solid var(--hair-2); margin: 0 4px 4px 0; color: var(--ink-2); }
  .edges { list-style: none; padding: 0; margin: 8px 0 0; display: grid; gap: 4px; }
  .edges li { font-size: 13px; }
  .edges button { background: none; border: 0; padding: 0; color: var(--accent); cursor: pointer; font: inherit; text-align: left; text-decoration: underline; }
  section.lists { padding: 20px 28px 40px; display: grid; grid-template-columns: repeat(auto-fit, minmax(320px, 1fr)); gap: 20px; border-top: 1px solid var(--hair); }
  section.lists h3 { font: 700 17px/1.2 Fraunces, Georgia, serif; margin: 0 0 8px; }
  section.lists ol { margin: 0; padding-left: 20px; color: var(--ink-2); font-size: 13.5px; display: grid; gap: 5px; }
  section.lists ol b { color: var(--ink); font-weight: 600; }
  .card { background: var(--surface); border: 1px solid var(--hair); border-radius: 10px; padding: 14px 16px; }
  .empty { color: var(--ink-3); font-style: italic; }
  @media (prefers-reduced-motion: reduce) { * { transition: none !important; } }
</style>

<header>
  <p class="eyebrow">Daliesk · research memory</p>
  <h1>Daliesk Knowledge Graph</h1>
  <p>Every paper, project, dataset, and finding the research so far rests on, linked to the four goal workflows and the seven design principles they inform. Select a node to read it; the right panel lists what it builds on, critiques, or measures.</p>
  <div class="stats" id="stats"></div>
</header>

<div class="layout">
  <aside class="filters">
    <div>
      <p class="eyebrow">Search</p>
      <input id="search" type="search" placeholder="title, author, id, theme" aria-label="Search nodes">
    </div>
    <div>
      <p class="eyebrow">Node types</p>
      <div class="chips" id="type-chips"></div>
    </div>
    <div>
      <p class="eyebrow">Workflows</p>
